package com.vk.kphpstorm.inspections

import com.intellij.codeInspection.LocalQuickFix
import com.intellij.codeInspection.ProblemsHolder
import com.intellij.psi.PsiElementVisitor
import com.jetbrains.php.lang.inspections.PhpInspection
import com.jetbrains.php.lang.psi.elements.FunctionReference
import com.jetbrains.php.lang.psi.elements.PhpReference
import com.jetbrains.php.lang.psi.visitors.PhpElementVisitor
import com.vk.kphpstorm.inspections.quickfixes.ReplaceUnsupportedFunctionCallQuickFix

class KphpUnsupportedFunctionCallInspection : PhpInspection() {
    companion object {
        private val PHP_TO_KPHP_FUNCTIONS = mapOf(
            "end" to listOf("array_last_value", "array_last_key"),
            "reset" to listOf("array_first_value", "array_first_key"),
        )
    }

    override fun buildVisitor(holder: ProblemsHolder, isOnTheFly: Boolean): PsiElementVisitor {
        return object : PhpElementVisitor() {
            override fun visitPhpFunctionCall(reference: FunctionReference) {
                if (reference.immediateNamespaceName != "" && reference.immediateNamespaceName != "\\")
                    return

                if ((reference as PhpReference).resolveLocal().isNotEmpty())
                    return

                val functionName = reference.name
                if (functionName !in PHP_TO_KPHP_FUNCTIONS.keys)
                    return

                val fixes = mutableListOf<LocalQuickFix>()

                val replaceFunction = PHP_TO_KPHP_FUNCTIONS[functionName]
                replaceFunction?.forEachIndexed { index, replaceFunctionName ->
                    fixes.add(ReplaceUnsupportedFunctionCallQuickFix(replaceFunctionName, index == 0))
                }

                holder.registerProblem(
                    reference,
                    "KPHP does not support $functionName()",
                    *fixes.toTypedArray(),
                )
            }
        }
    }
}

package com.vk.kphpstorm.inspections.quickfixes

import com.intellij.codeInspection.LocalQuickFix
import com.intellij.codeInspection.ProblemDescriptor
import com.intellij.openapi.project.Project
import com.intellij.psi.util.PsiTreeUtil
import com.jetbrains.php.lang.lexer.PhpTokenTypes
import com.jetbrains.php.lang.psi.PhpPsiElementFactory
import com.jetbrains.php.lang.psi.elements.FunctionReference
import com.jetbrains.php.lang.psi.elements.PhpNamespaceReference

class ReplaceUnsupportedFunctionCallQuickFix(
    private val replaceFunction: String,
    private val isFirst: Boolean = false
) : LocalQuickFix {
    override fun getFamilyName(): String {
        return if (isFirst) {
            "Maybe use $replaceFunction()"
        } else {
            "Replace with $replaceFunction()"
        }
    }

    override fun applyFix(project: Project, descriptor: ProblemDescriptor) {
        val unsupportedFunction = descriptor.psiElement
        if (unsupportedFunction !is FunctionReference)
            return

        val unsupportedFunctionNameNode = unsupportedFunction.nameNode ?: return

        val newFunctionNameNode = PhpPsiElementFactory.createFromText(
            project,
            PhpTokenTypes.IDENTIFIER,
            replaceFunction
        ).node

        if (unsupportedFunction.namespaceName == "\\") {
            val namespaceReference = PsiTreeUtil.findChildOfType(unsupportedFunction, PhpNamespaceReference::class.java)
            namespaceReference?.delete()
        }

        unsupportedFunction.node.replaceChild(
            unsupportedFunctionNameNode,
            newFunctionNameNode
        )
    }
}

